// Only real forward audio progress counts; pause, seek, switching and opt-out reset baselines.
export function createListeningMeter({onProgress=()=>{}}={}){let previous=null;const seconds=new Map();return{reset(){previous=null;seconds.clear();},sample(state,now,enabled){if(!enabled){this.reset();return [];}const current={id:state.reciter,surah:state.surah?.number,index:state.index,position:Number(state.positionSeconds),playing:state.status==='playing',now};if(previous&&(current.playing||['paused','ended'].includes(state.status))&&previous.playing&&current.id===previous.id&&current.surah===previous.surah&&Number.isFinite(current.position)&&Number.isFinite(previous.position)){const elapsed=(now-previous.now)/1000,progress=current.position-previous.position;if(elapsed>0&&elapsed<=43200&&progress>0&&progress<=elapsed*4+1){const credited=Math.min(elapsed,progress);seconds.set(current.id,(seconds.get(current.id)||0)+credited);onProgress(current.id,credited);}}previous=current;const ready=[];for(const [id,n]of seconds)if(n>=60){seconds.set(id,n-60);ready.push(id);}return ready;}};}

export function formatListeningTime(seconds){const minutes=Math.floor(Math.max(0,Number(seconds)||0)/60);if(!minutes)return seconds>0?'Меньше минуты':'0 ч 0 мин';return Math.floor(minutes/60)+' ч '+minutes%60+' мин';}
